WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')), base AS (SELECT COALESCE(e.nome, 'não informado') AS executivo, COALESCE(p.segmento, 'não informado') AS segmento, p.status, COALESCE(p.fonte, 'sem catálogo') AS fonte, COALESCE(p.preco, 'sem catálogo') AS preco, to_char(p.criado_em, 'YYYY-MM') AS mes, p.produtos, p.custo_ia_usd, EXTRACT(EPOCH FROM (p.concluido_em - p.criado_em)) AS seg_total, EXTRACT(EPOCH FROM (p.concluido_em - p.criacao_inicio)) AS seg_criacao FROM pedidos p JOIN eu ON (eu.admin OR p.executivo_id = eu.executivo_id) LEFT JOIN executivos e ON e.id = p.executivo_id WHERE (NOT eu.admin OR :executivo IS NULL OR :executivo = '' OR p.executivo_id = CAST(:executivo AS INTEGER)) AND (:segmento IS NULL OR :segmento = '' OR p.segmento = :segmento) AND (:status IS NULL OR :status = '' OR p.status = :status) AND (:desde IS NULL OR :desde = '' OR p.criado_em >= CAST(:desde AS DATE)) AND (:ate IS NULL OR :ate = '' OR p.criado_em < CAST(:ate AS DATE) + 1)) SELECT CASE WHEN GROUPING(executivo) = 0 THEN 'executivo' WHEN GROUPING(segmento) = 0 THEN 'segmento' WHEN GROUPING(status) = 0 THEN 'status' WHEN GROUPING(fonte) = 0 THEN 'fonte' WHEN GROUPING(preco) = 0 THEN 'preco' WHEN GROUPING(mes) = 0 THEN 'periodo' ELSE 'total' END AS dimensao, COALESCE(executivo, segmento, status, fonte, preco, mes, 'total') AS valor, count(*) AS pedidos, count(*) FILTER (WHERE status = 'concluido') AS concluidos, count(*) FILTER (WHERE status = 'falhou') AS falharam, count(*) FILTER (WHERE status = 'curadoria') AS em_curadoria, count(*) FILTER (WHERE status = 'precisa_catalogo') AS precisa_catalogo, count(*) FILTER (WHERE status IN ('extraindo', 'criando')) AS em_andamento, round(avg(seg_total)) AS tempo_medio_s, round(avg(seg_criacao)) AS tempo_criacao_s, round(avg(produtos), 1) AS produtos_medio, round(sum(custo_ia_usd), 4) AS custo_ia_usd FROM base GROUP BY GROUPING SETS ((executivo), (segmento), (status), (fonte), (preco), (mes), ()) ORDER BY 1, 3 DESC LIMIT 500
